import { SCENARIOS } from "../content/battles";
import { ITEMS } from "../content/items";
import { QUEST_TEMPLATES } from "../content/templates";
import { LEVEL_CURVE_V1 } from "../domain/levels";

/**
 * Reference content for the database, generated from the TypeScript catalogs so the server's copy is
 * always identical. `npm run earned:seed` writes supabase/seed.sql from this.
 */

const q = (v: string) => `'${v.replace(/'/g, "''")}'`;
const j = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;

export function seedSql(): string {
  const lines: string[] = [
    "-- Generated by `npm run earned:seed` from lib/earned/content and lib/earned/domain/levels.ts. Do not edit by hand.",
    "begin;",
    `insert into earned.level_config_versions (id, version, config) values (${q(`v${LEVEL_CURVE_V1.version}`)}, ${LEVEL_CURVE_V1.version}, ${j(LEVEL_CURVE_V1)}) on conflict (id) do nothing;`,
  ];
  for (const t of QUEST_TEMPLATES) {
    lines.push(
      `insert into earned.quest_templates (id, version, category, title, content) values (${q(t.id)}, 1, ${q(t.category)}, ${q(t.title)}, ${j(t)}) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;`,
    );
  }
  for (const i of ITEMS) {
    lines.push(
      `insert into earned.item_definitions (id, kind, slot, rarity, name, description, stats, is_unique, art, color) values (${q(i.id)}, ${q(i.kind)}, ${i.slot ? q(i.slot) : "null"}, ${q(i.rarity)}, ${q(i.name)}, ${q(i.description)}, ${j(i.stats ?? {})}, ${i.unique}, ${q(i.art)}, ${q(i.color)}) on conflict (id) do update set kind = excluded.kind, slot = excluded.slot, rarity = excluded.rarity, name = excluded.name, description = excluded.description, stats = excluded.stats, is_unique = excluded.is_unique, art = excluded.art, color = excluded.color;`,
    );
  }
  for (const s of SCENARIOS) {
    lines.push(
      `insert into earned.battle_definitions (id, version, category, title, content) values (${q(s.id)}, ${s.version}, ${q(s.category)}, ${q(s.title)}, ${j(s)}) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;`,
    );
  }
  lines.push("commit;", "");
  return lines.join("\n");
}
